import growingTipsData from "../data/growing_tips.json" with { type: "json" };
import enterpriseData from "../data/enterprises.json" with { type: "json" };

// AI-suggested growing tips (companion planting, soil amendment, pest
// management, multi-year rotation), generated by local LLMs (currently
// Qwen2.5-7B and Llama 3.1 8B, more may be added later) answering well-
// scoped questions over gram's real eligible crop scenarios, then merged
// and fact-checked against this app's own sourced data (rotation.js's
// ROTATION_TRAITS) -- see ml/knowledge_dataset/build_growing_tips.mjs for
// exactly what the merge and fact-check do and don't catch.
//
// This is explicitly NOT the same trust level as enterprises.json's
// cited economics/agronomics data: it's un-cross-validated model output, so
// every consumer of this data must surface it as "AI-suggested, not yet
// verified" rather than presenting it with the same confidence as the rest
// of the app.
//
// Shape per (cropId, zone, season):
//   companionPlanting / pestDisease: [{ name, detail, confidence, sources,
//     confirmed }] -- `sources` lists which model(s) named this entry;
//     `confirmed: true` means 2+ models independently named the same one
//     (the strongest signal here), `false` means only one model did (still
//     kept, just not corroborated -- never silently dropped).
//   soilAmendment / rotationSequence: { bySource: [{ model, text,
//     confidence, factCheckWarnings }] } -- one paragraph per model that
//     answered, kept side by side rather than merged into an invented
//     synthesis neither model actually said. factCheckWarnings means a
//     specific sentence in that model's text was checked and found to
//     contradict real data -- the text is still returned (may still be
//     useful) but the warning must be shown alongside it, never dropped.
export function getGrowingTips(cropId, zone, season) {
  return growingTipsData.tips?.[cropId]?.[zone]?.[season] ?? null;
}

export const growingTipsMeta = {
  generatedFrom: growingTipsData.generatedFrom,
  generatedAt: growingTipsData.generatedAt,
};

// ---------- AI-suggested companion planting -> Shuffle cross-reference ----------
// growing_tips.json's companionPlanting entries name a companion in free text
// (an LLM's own words: "Cowpea", "Arachis hypogaea", "Sesbania (Dhaincha)",
// "Fish (rice-fish culture)"...), not a gram enterprise id. Most of them
// aren't a plantable gram enterprise at all -- green manures, cover crops,
// weeds, fish -- so they have nothing to cross-reference against a Shuffle
// layout's own crop segments. Resolution here is deliberately conservative:
// exact match against the catalog's own name (parenthetical local-name
// stripped) plus a short list of individually-verified scientific-name
// aliases for the handful of catalog crops an LLM commonly names in Latin.
// Anything that doesn't resolve is simply skipped, not guessed at -- see
// the "data honesty over completeness" principle used throughout this app.
const SCIENTIFIC_NAME_ALIASES = {
  "arachis hypogaea": "groundnut",
  "trichosanthes cucumerina": "snake_gourd",
  "glycine max": "soybean",
  "cajanus cajan": "pigeon_pea",
  "vigna unguiculata": "cowpea",
  "brassica juncea": "mustard",
};

function bareName(name) {
  return name.replace(/\s*\(.*?\)\s*/g, "").trim().toLowerCase();
}

let nameToIdMap = null;
function getNameToIdMap() {
  if (nameToIdMap) return nameToIdMap;
  nameToIdMap = new Map();
  for (const e of enterpriseData.enterprises) nameToIdMap.set(bareName(e.name), e.id);
  for (const [alias, id] of Object.entries(SCIENTIFIC_NAME_ALIASES)) {
    if (!nameToIdMap.has(alias)) nameToIdMap.set(alias, id);
  }
  return nameToIdMap;
}

// Only "medium"/"high" band claims are eligible -- same default-shown
// threshold GrowingTips.jsx already uses, so a Shuffle layout never
// surfaces a companion suggestion the farmer wouldn't already see by
// default in that crop's own growing-tips accordion.
const ELIGIBLE_BANDS = new Set(["high", "medium"]);

// Cross-references growing_tips.json's AI-suggested companion-planting
// claims against crops that are ACTUALLY placed together in one Shuffle
// field layout -- e.g. if rice's companionPlanting list names "Cowpea" and
// cowpea is also a segment in this same layout, that's a real, checkable
// coincidence worth surfacing, not an invented pairing. Deliberately
// informational only: the caller must never fold this into productivityScore,
// profit, or layout ranking/selection -- only scoring.js's own cited
// COMPANION_RELATIONSHIPS is allowed to touch real numbers. See
// fieldLayouts.js and FieldLayoutCard for how this stays a separate,
// clearly-labeled "unverified" section.
export function findAiCompanionMatches(cropIds, zone, season) {
  const nameToId = getNameToIdMap();
  const idToName = new Map(enterpriseData.enterprises.map((e) => [e.id, e.name]));
  const idSet = new Set(cropIds);
  const seenPairs = new Set();
  const matches = [];

  for (const cropId of cropIds) {
    const tips = getGrowingTips(cropId, zone, season);
    for (const entry of tips?.companionPlanting ?? []) {
      if (!ELIGIBLE_BANDS.has(entry.probabilityBand)) continue;
      const otherId = nameToId.get(bareName(entry.name));
      if (!otherId || otherId === cropId || !idSet.has(otherId)) continue;
      const pairKey = [cropId, otherId].sort().join("+");
      if (seenPairs.has(pairKey)) continue;
      seenPairs.add(pairKey);
      matches.push({
        cropIds: [cropId, otherId],
        cropNames: [idToName.get(cropId), idToName.get(otherId)],
        detail: entry.detail,
        confidence: entry.probabilityBand,
        sources: entry.sources,
      });
    }
  }
  return matches;
}
